  'page_js' => '// click-to-load YouTube Shorts
document.querySelectorAll(\'.short\').forEach(function(card){
  card.addEventListener(\'click\', function(){
    var vid = card.dataset.vid;
    if(!vid || vid.indexOf(\'YOUTUBE_ID\') === 0) return;
    var t = card.querySelector(\'.thumb\');
    var f = document.createElement(\'iframe\');
    f.src = \'https://www.youtube.com/embed/\' + vid + \'?autoplay=1&playsinline=1\';
    f.allow = \'autoplay; encrypted-media; picture-in-picture\';
    f.allowFullscreen = true;
    t.appendChild(f);
  });
});

// hero chip count-up
(function(){
  var els=document.querySelectorAll(\'.hero-chip .cnt\');
  if(!els.length) return;
  if(matchMedia(\'(prefers-reduced-motion: reduce)\').matches){
    els.forEach(function(e){e.textContent=(+e.dataset.to).toLocaleString(\'en-IN\')+e.dataset.suf}); return;
  }
  els.forEach(function(e){
    var to=+e.dataset.to, suf=e.dataset.suf, t0=null, dur=1400;
    function step(t){ if(!t0)t0=t; var k=Math.min((t-t0)/dur,1); k=1-Math.pow(1-k,3);
      e.textContent=Math.round(to*k).toLocaleString(\'en-IN\')+suf;
      if(k<1) requestAnimationFrame(step); }
    setTimeout(function(){requestAnimationFrame(step)}, 500);
  });
})();



// hero card deck: fan turn
(function(){
  var deck=document.getElementById(\'heroDeck\'); if(!deck) return;
  var cards=[].slice.call(deck.querySelectorAll(\'.hcard\'));
  var cur=0, busy=false, timer=null;
  function paint(){cards.forEach(function(c,i){
    c.classList.remove(\'hf0\',\'hf1\',\'hf2\',\'hfly\');
    c.classList.add(\'hf\'+((i-cur+cards.length)%cards.length));});}
  function tick(){ if(busy) return; busy=true;
    cards[cur].classList.add(\'hfly\');
    setTimeout(function(){cur=(cur+1)%cards.length; paint(); busy=false;},420);}
  function restart(){clearInterval(timer);
    if(!matchMedia(\'(prefers-reduced-motion: reduce)\').matches) timer=setInterval(tick,4000);}
  deck.addEventListener(\'mouseenter\',function(){clearInterval(timer)});
  deck.addEventListener(\'mouseleave\',restart);
  paint(); restart();
})();

// mode filter
(function(){
  var pills=[].slice.call(document.querySelectorAll(\'#modePills .mode\'));
  var cards=[].slice.call(document.querySelectorAll(\'#courses .ccard\'));
  pills.forEach(function(pl){
    pl.addEventListener(\'click\',function(){
      pills.forEach(function(x){x.classList.remove(\'on\')});
      pl.classList.add(\'on\');
      var m=pl.dataset.mode;
      var shown=0;
      cards.forEach(function(c){
        var ok = m===\'any\' || (c.dataset.modes||\'\').split(\' \').indexOf(m)>-1;
        c.classList.toggle(\'mhide\',!ok); if(ok) shown++;
      });
      var fc=document.getElementById(\'fCount\');
      if(fc) fc.textContent = m===\'any\' ? \'Showing all \'+shown+\' courses\' : \'Showing \'+shown+\' of \'+cards.length+\' courses\';
    });
  });
})();',
];
